import data from "./example.json";

// EXAMPLE numbers only. Generated by running four made-up debts through the app's own payoff engine
// (see scripts/gen-example.cjs). They are not real users, results or promises.
export type Series = { months: number; totalInterest: number; totalPaid: number; order: { name: string; month: number }[]; balance: number[] };

export const EXAMPLE = data as {
  extra: number;
  debts: { id: string; name: string; balance: number; apr: number; minPayment: number }[];
  snowball: Series;
  avalanche: Series;
  minimumsOnly: Series;
};

export const usd = (n: number, decimals = 0) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(n);

export const START_TOTAL = EXAMPLE.debts.reduce((s, d) => s + d.balance, 0);
export const FIRST_WIN = {
  avalanche: EXAMPLE.avalanche.order[0],
  snowball: EXAMPLE.snowball.order[0],
};
export const INTEREST_GAP = Math.round((EXAMPLE.snowball.totalInterest - EXAMPLE.avalanche.totalInterest) * 100) / 100;

const BUDGET = EXAMPLE.debts.reduce((s, d) => s + d.minPayment, 0) + EXAMPLE.extra;
const round2 = (n: number) => Math.round(n * 100) / 100;

/** Cumulative interest paid by the end of each month (index 0 = today). The monthly budget is constant until the final month. */
export function cumulativeInterest(s: Series): number[] {
  const out = [0];
  let sum = 0;
  for (let t = 1; t < s.balance.length; t++) {
    const last = t === s.balance.length - 1;
    const i = last ? s.totalInterest - sum : s.balance[t] - s.balance[t - 1] + BUDGET;
    sum += i;
    out.push(round2(sum));
  }
  return out;
}

/** How many debts are still open at the end of each month. */
export function openDebts(s: Series): number[] {
  return s.balance.map((_, t) => EXAMPLE.debts.length - s.order.filter((o) => o.month <= t).length);
}

/** Extra interest the snowball plan has paid over the avalanche plan, month by month. */
export function snowballExtraInterest(): number[] {
  const a = cumulativeInterest(EXAMPLE.avalanche);
  const s = cumulativeInterest(EXAMPLE.snowball);
  return s.map((v, i) => round2(v - a[i]));
}
